public import AemiProtobuf

/// `message Profile { string bio = 1; optional string company = 2; int64 public_repos = 3; optional string location = 4; }`,
/// with the fast path and `Codable` generated by `@ProtoMessage`.
@ProtoMessage
public struct ProtoProfile: Equatable {
    @ProtoField(1) public var bio: String = ""
    @ProtoField(2) public var company: String? = nil
    @ProtoField(3) public var publicRepos: Int64 = 0
    @ProtoField(4) public var location: String? = nil
}
